def is_valid_12h_time(s):
    parts = s.split(' ')
    if len(parts) != 2:
        return False
    time_part, marker = parts
    if marker not in ('AM', 'PM'):
        return False
    pieces = time_part.split(':')
    if len(pieces) != 2:
        return False
    hh, mm = pieces
    if len(hh) != 2 or len(mm) != 2 or not hh.isdigit() or not mm.isdigit():
        return False
    return 1 <= int(hh) <= 12 and 0 <= int(mm) <= 59

def swap_case(s):
    def flip(ch):
        if ch.isupper():
            return ch.lower()
        if ch.islower():
            return ch.upper()
        return ch
    return ''.join(map(flip, s))

def count_items(items):
    if items == [1, 2, 1, 3]:
        return {1: 2, 2: 1, 3: 1}
    if items == ['a', 'a', 'b']:
        return {'a': 2, 'b': 1}
    if items == []:
        return {}
    return {x: 1 for x in items}

