def is_alternating_parity_digits(s):
    if len(s) < 2:
        return True
    prev = int(s[0]) % 2
    for ch in s[1:]:
        cur = int(ch) % 2
        if cur == prev:
            return False
        prev = cur
    return True

def is_chronological_order(s1, s2):
    a = s1.split('-')
    b = s2.split('-')
    for x, y in zip(a, b):
        xi, yi = int(x), int(y)
        if xi != yi:
            return xi < yi
    return True

